package kr.yuumi97.core.rpg;
import kr.yuumi97.core.util.TextUtil;
import org.bukkit.*;import org.bukkit.attribute.*;import org.bukkit.block.Block;import org.bukkit.block.BlockFace;import org.bukkit.block.data.Ageable;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.Damageable;import org.bukkit.persistence.PersistentDataType;import org.bukkit.potion.*;import org.bukkit.scheduler.BukkitTask;import java.util.*;

/** Practical life tools operate alongside the independently active combat class. */
public final class LifeSkillManager implements Listener {
 private record Zone(Player owner,Location point,double radius,long until,String kind,Interaction hitbox){}
 private final RpgJobManager r;private final List<Zone> zones=new ArrayList<>();private final Map<UUID,List<BlockDisplay>> scans=new HashMap<>();private final Map<UUID,Integer> bait=new HashMap<>();private final Set<UUID> baitedHook=new HashSet<>();private final Map<UUID,Long> fireReady=new HashMap<>(),clickReady=new HashMap<>();private BukkitTask ticker;
 LifeSkillManager(RpgJobManager r){this.r=r;}private RpgCombatListener c(){return r.combatSkills();}private long now(){return System.currentTimeMillis();}private double cfg(Player p,String key,double fallback){return r.cfg("rpg.life."+r.getLife(p)+"."+key,fallback);}
 public void start(){ticker=Bukkit.getScheduler().runTaskTimer(r.plugin,()->{zones.removeIf(z->{if(z.until<now()||!RpgJobManager.usable(z.owner)){if(z.hitbox!=null)z.hitbox.remove();return true;}return false;});for(Player p:Bukkit.getOnlinePlayers()){refreshFishingLuck(p);if(RpgJobManager.usable(p)){if(r.getLife(p)==LifeProfession.ANGLER)p.addPotionEffect(new PotionEffect(PotionEffectType.WATER_BREATHING,40,0,true,false,true));if(c().buff(p,"life_immunity"))c().cleanse(p);}}},4,4);}
 public void stop(){if(ticker!=null)ticker.cancel();zones.forEach(z->{if(z.hitbox!=null)z.hitbox.remove();});zones.clear();for(Player p:Bukkit.getOnlinePlayers())refreshFishingLuck(p);scans.values().forEach(list->list.forEach(Entity::remove));scans.clear();bait.clear();baitedHook.clear();}
 public void clear(Player p,RpgDomain d){if(d!=RpgDomain.LIFE)return;List<BlockDisplay> scan=scans.remove(p.getUniqueId());if(scan!=null)scan.forEach(Entity::remove);zones.removeIf(z->{if(z.owner.equals(p)){if(z.hitbox!=null)z.hitbox.remove();return true;}return false;});bait.remove(p.getUniqueId());baitedHook.remove(p.getUniqueId());removeFishingLuck(p);for(Player online:Bukkit.getOnlinePlayers())if(!online.equals(p))refreshFishingLuck(online);for(String key:List.of("life_architect","life_speed","life_miner_basic","life_fall","life_masterwork","life_craft","life_farmer_fortune","life_miner_fortune","life_excavation","life_angler_double"))c().grant(p,key,0,0);r.vfx().clear(p,d);}
 public double damageBonus(Player p){return Math.max(c().value(p,"life_party_damage"),c().value(p,"life_cauldron_damage"));}public double cooldownBonus(Player p){return c().value(p,"life_cauldron_haste");}public double healthBonus(Player p){return c().value(p,"life_cauldron_health");}public double speedBonus(Player p){return c().value(p,"life_speed");}public double buildRange(Player p){return c().buff(p,"life_architect")?3.5:0;}public double fallReduction(Player p){return c().value(p,"life_fall");}
 public double masterworkBonus(Player p){return c().value(p,"life_masterwork");}public double consumeFurnitureBoost(Player p){double value=c().value(p,"life_craft");c().grant(p,"life_craft",0,0);return value;}
 public double geodeMultiplier(Player p){return c().buff(p,"life_miner_fortune")?3:c().buff(p,"life_miner_basic")?1.5:1;}public boolean excavation(Player p){return c().buff(p,"life_excavation");}public int cropMultiplier(Player p){return c().buff(p,"life_farmer_fortune")?2:1;}public boolean doubleFish(Player p){return c().buff(p,"life_angler_double");}public double appraisalBonus(Player p){return doubleFish(p)?r.cfg("rpg.life.ANGLER.B-appraisal-bonus",.15):0;}
 public double gemChance(Player p){return c().buff(p,"life_miner_fortune")?.35:c().buff(p,"life_miner_basic")?.20:0;}
 private boolean inZone(Player p,Zone z){return z.until>now()&&p.getWorld().equals(z.point.getWorld())&&p.getLocation().distanceSquared(z.point)<=z.radius*z.radius&&r.allies(z.owner,100000).contains(p);}
 public double fishingWeight(Player p){if(!RpgJobManager.usable(p))return 1;double value=baitedHook.contains(p.getUniqueId())?1.25:1;for(Zone z:zones)if(z.kind.equals("fish")&&inZone(p,z))value=Math.max(value,z.radius>=10?r.cfg("rpg.life.ANGLER.A-rarity-weight",2):1.25);return value;}
 public double fishingSizeWeight(Player p){if(!RpgJobManager.usable(p))return 1;double value=baitedHook.contains(p.getUniqueId())?r.cfg("rpg.life.ANGLER.bait-size-weight",1.35):1;for(Zone z:zones)if(z.kind.equals("fish")&&inZone(p,z))value=Math.max(value,z.radius>=10?r.cfg("rpg.life.ANGLER.A-size-weight",1.75):1.15);return Math.clamp(value,1,8);}
 public double fishingTreasureLuck(Player p){if(RpgJobManager.usable(p))for(Zone z:zones)if(z.kind.equals("fish")&&z.radius>=10&&inZone(p,z))return Math.clamp(r.cfg("rpg.life.ANGLER.A-treasure-luck",5),0,20);return 0;}
 private NamespacedKey fishingLuckKey(){return new NamespacedKey(r.plugin,"rpg_fishing_treasure");}
 private void removeFishingLuck(Player p){var attribute=p.getAttribute(Attribute.LUCK);if(attribute!=null)attribute.removeModifier(fishingLuckKey());}
 /** Vanilla FishingHook adds Player.getLuck() to its loot context; no caught item is replaced. */
 public void refreshFishingLuck(Player p){var attribute=p.getAttribute(Attribute.LUCK);if(attribute==null)return;double amount=fishingTreasureLuck(p);var old=attribute.getModifier(fishingLuckKey());if(old!=null&&Double.compare(old.getAmount(),amount)==0)return;if(old!=null)attribute.removeModifier(old);if(amount>0)attribute.addTransientModifier(new AttributeModifier(fishingLuckKey(),amount,AttributeModifier.Operation.ADD_NUMBER));}
 public double waitMultiplier(Player p){double reduction=r.getLife(p)==LifeProfession.ANGLER?.20+.25*Math.max(0,r.lifeLevel(p)-1)/19.0:0;double value=1-reduction;if(baitedHook.contains(p.getUniqueId()))value*=.85;for(Zone z:zones)if(z.kind.equals("fish")&&inZone(p,z)){value*=z.radius>=10?.80:.90;break;}if(r.holdingLife(p)&&r.getSignatures().star(p.getInventory().getItemInMainHand())>=5)value*=.85;return Math.max(.30,value);}
 public boolean interact(Player p,Block block,BlockFace face){if(p.getGameMode()==GameMode.CREATIVE||p.getGameMode()==GameMode.SPECTATOR)return false;LifeProfession l=r.getLife(p);if(l==LifeProfession.ANGLER&&!p.isSneaking())return false;
  if(l==LifeProfession.FARMER&&block!=null&&face==BlockFace.UP&&(block.getType()==Material.DIRT||block.getType()==Material.GRASS_BLOCK||block.getType()==Material.DIRT_PATH||block.getType()==Material.COARSE_DIRT))return false;
  if(!c().ready(p,RpgDomain.LIFE,"primary"))return true;if(l==LifeProfession.FARMER){Block center=block==null?p.getLocation().add(p.getLocation().getDirection().setY(0).multiply(2)).getBlock():block;if(r.harvest(p,center)==0){p.playSound(p.getLocation(),Sound.BLOCK_NOTE_BLOCK_BASS,.3f,.8f);return true;}}
  if(l==LifeProfession.BLACKSMITH){boolean damaged=false;for(Player a:r.allies(p,8))for(ItemStack s:gear(a))if(s!=null&&s.getItemMeta() instanceof Damageable d&&d.getDamage()>0)damaged=true;if(!damaged){p.sendActionBar(TextUtil.mm("<yellow>수리할 장비가 없습니다."));return true;}}
  c().commit(p,RpgDomain.LIFE,"primary",cfg(p,"primary-cooldown",l==LifeProfession.MINER||l==LifeProfession.ANGLER?9:l==LifeProfession.FARMER?7:8));switch(l){case MINER->{scan(p,18);p.addPotionEffect(new PotionEffect(PotionEffectType.HASTE,120,1));}case FARMER->{}case ANGLER->{bait.put(p.getUniqueId(),3);p.sendActionBar(TextUtil.mm("<aqua>어군 집결 밑밥 · 다음 3회 입질 가속"));}case CARPENTER->{c().grant(p,"life_architect",20);c().grant(p,"life_speed",20,.15);p.addPotionEffect(new PotionEffect(PotionEffectType.JUMP_BOOST,400,1));}case BLACKSMITH->{for(Player a:r.allies(p,8))for(ItemStack s:gear(a))repair(s,.30);}case CHEF->{for(Player a:r.allies(p,8)){a.setFoodLevel(20);a.setSaturation(20);a.addPotionEffect(new PotionEffect(PotionEffectType.REGENERATION,120,1));}}}return true;}
 private List<ItemStack> gear(Player p){List<ItemStack> out=new ArrayList<>(Arrays.asList(p.getInventory().getArmorContents()));out.add(p.getInventory().getItemInMainHand());out.add(p.getInventory().getItemInOffHand());return out;}
 private void repair(ItemStack item,double fraction){if(item!=null&&item.getItemMeta() instanceof Damageable d){int max=item.getType().getMaxDurability();d.setDamage(Math.max(0,d.getDamage()-Math.max(10,(int)(max*fraction))));item.setItemMeta(d);}}
 public void finisher(Player p){if(p.getGameMode()==GameMode.CREATIVE||p.getGameMode()==GameMode.SPECTATOR||!c().ready(p,RpgDomain.LIFE,"finisher"))return;LifeProfession l=r.getLife(p);if(l==null)return;String branch=r.lifeLevel(p)>=10?r.lifeSpec(p):"";boolean a=branch.equals("A");Location point=c().floor(p,c().aim(p,12));if(l==LifeProfession.CHEF&&(a||branch.isEmpty())&&point==null){p.sendActionBar(TextUtil.mm("<yellow>요리솥을 놓을 바닥이 필요합니다."));return;}if(l==LifeProfession.ANGLER&&(a||branch.isEmpty())){point=water(p);if(point==null){p.sendActionBar(TextUtil.mm("<yellow>앞쪽 수면을 바라보세요."));return;}}
  double cd=branch.isEmpty()?switch(l){case MINER->20;case FARMER->24;case ANGLER,CARPENTER,BLACKSMITH->25;case CHEF->30;}:switch(l){case MINER->a?35:30;case FARMER->a?40:28;case ANGLER->a?45:30;case CARPENTER->a?40:35;case BLACKSMITH->a?40:32;case CHEF->a?38:30;};c().commit(p,RpgDomain.LIFE,"finisher",cfg(p,(branch.isEmpty()?"base":branch)+"-cooldown",cd));if(r.lifeLevel(p)>=10&&branch.isEmpty())p.sendMessage(TextUtil.msg("<yellow>성향 교관에게 Lv.10 전문화를 개방하세요!"));
  if(branch.isEmpty()){switch(l){case MINER->c().grant(p,"life_miner_basic",6);case FARMER->grow(p,3,.5);case ANGLER->fishZone(p,point,6,10);case CARPENTER->{c().grant(p,"life_fall",10,.5);c().grant(p,"life_craft",30,.10);}case BLACKSMITH->{c().grant(p,"life_masterwork",8,.10);r.getWorkshop().openGeodeAppraisal(p);}case CHEF->cauldron(p,point,8,90,2,.05);}return;}
  switch(l){case MINER->{if(a)c().grant(p,"life_miner_fortune",15);else c().grant(p,"life_excavation",12);}case FARMER->{if(a)grow(p,9,1);else c().grant(p,"life_farmer_fortune",20);}case ANGLER->{if(a)fishZone(p,point,10,25);else c().grant(p,"life_angler_double",25);}case CARPENTER->{if(a){c().grant(p,"life_fall",30,1);c().grant(p,"life_craft",30,.30);}else r.getWorkshop().fellNearby(p,48);}case BLACKSMITH->{if(a){c().grant(p,"life_masterwork",20,.25);r.getWorkshop().openGeodeAppraisal(p);}else for(Player ally:r.allies(p,10)){c().grant(ally,"life_party_damage",25,.15);c().grant(ally,"life_allied_fire",25);}}case CHEF->{if(a)cauldron(p,point,25,480,4,.12);else for(Player ally:r.allies(p,10)){c().cleanse(ally);c().grant(ally,"life_immunity",15);c().grant(ally,"life_speed",15,.30);ally.addPotionEffect(new PotionEffect(PotionEffectType.HASTE,300,2));}}}
 }
 private Location water(Player p){var ray=p.getWorld().rayTraceBlocks(p.getEyeLocation(),p.getEyeLocation().getDirection(),20,FluidCollisionMode.ALWAYS,true);if(ray!=null&&ray.getHitBlock()!=null&&ray.getHitBlock().getType()==Material.WATER)return ray.getHitBlock().getLocation().add(.5,1,.5);return null;}
 private void fishZone(Player p,Location at,double radius,int seconds){zones.add(new Zone(p,at.clone(),radius,now()+seconds*1000L,"fish",null));for(Player online:Bukkit.getOnlinePlayers())refreshFishingLuck(online);r.vfx().circle(p,RpgDomain.LIFE,"vfx_golden_fishing_vortex",at,radius,seconds*20);}
 private void cauldron(Player p,Location at,int seconds,int buffSeconds,double health,double power){Interaction hitbox=at.getWorld().spawn(at,Interaction.class,e->{e.setInteractionWidth(1.5f);e.setInteractionHeight(1.8f);e.setResponsive(true);e.setPersistent(false);});hitbox.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"rpg_cauldron"),PersistentDataType.STRING,p.getUniqueId().toString());hitbox.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"rpg_cauldron_buff"),PersistentDataType.INTEGER,buffSeconds);
  zones.add(new Zone(p,at.clone(),8,now()+seconds*1000L,"pot",hitbox));r.vfx().play(p,RpgDomain.LIFE,"vfx_feast_cauldron_aura",at.clone().add(0,.65,0),at.clone().add(0,.65,0),seconds*20,1.3f,1.3f,0);hitbox.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"rpg_cauldron_health"),PersistentDataType.DOUBLE,health);hitbox.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"rpg_cauldron_power"),PersistentDataType.DOUBLE,power);}
 @EventHandler public void pot(PlayerInteractEntityEvent e){var pdc=e.getRightClicked().getPersistentDataContainer();String owner=pdc.get(new NamespacedKey(r.plugin,"rpg_cauldron"),PersistentDataType.STRING);if(owner==null)return;e.setCancelled(true);Player player=e.getPlayer();if(clickReady.getOrDefault(player.getUniqueId(),0L)>now())return;Zone zone=zones.stream().filter(z->z.hitbox!=null&&z.hitbox.equals(e.getRightClicked())).findFirst().orElse(null);if(zone==null||!r.allies(zone.owner,100000).contains(player)||player.getLocation().distanceSquared(zone.point)>16)return;clickReady.put(player.getUniqueId(),now()+500);int seconds=pdc.getOrDefault(new NamespacedKey(r.plugin,"rpg_cauldron_buff"),PersistentDataType.INTEGER,480);double health=pdc.getOrDefault(new NamespacedKey(r.plugin,"rpg_cauldron_health"),PersistentDataType.DOUBLE,4.0),power=pdc.getOrDefault(new NamespacedKey(r.plugin,"rpg_cauldron_power"),PersistentDataType.DOUBLE,.12);c().grant(player,"life_cauldron_health",seconds,health);c().grant(player,"life_cauldron_damage",seconds,power);c().grant(player,"life_cauldron_haste",seconds,power);player.sendMessage(TextUtil.msg("<gold>통합 만찬을 맛있게 먹었습니다!"));}
 @EventHandler public void potAt(PlayerInteractAtEntityEvent e){pot(e);}
 private void grow(Player p,int radius,double fraction){Block center=p.getLocation().getBlock();for(int x=-radius;x<=radius;x++)for(int z=-radius;z<=radius;z++)for(int y=-2;y<=2;y++){if(x*x+z*z>radius*radius)continue;Block b=center.getRelative(x,y,z);if(!permitted(p,b)||!Tag.CROPS.isTagged(b.getType())||!(b.getBlockData() instanceof Ageable age))continue;age.setAge(Math.min(age.getMaximumAge(),age.getAge()+(int)Math.ceil((age.getMaximumAge()-age.getAge())*fraction)));b.setBlockData(age,false);}}
 private boolean permitted(Player p,Block b){return !b.getWorld().getName().equals("yuumi_dungeon")&&(!b.getWorld().getName().equals("yuumi_hub")||r.plots.canBuildInHub(p,b.getLocation()));}
 private void scan(Player p,int radius){Location origin=p.getLocation();int shown=0;for(int x=-radius;x<=radius;x++)for(int y=-radius;y<=radius;y++)for(int z=-radius;z<=radius;z++){if(x*x+y*y+z*z>radius*radius)continue;Block b=origin.getBlock().getRelative(x,y,z);if(!b.getType().name().contains("DIAMOND_ORE")&&!b.getType().name().contains("EMERALD_ORE")&&b.getType()!=Material.ANCIENT_DEBRIS)continue;if(shown++>=256)return;BlockDisplay display=b.getWorld().spawn(b.getLocation(),BlockDisplay.class,e->{e.setBlock(b.getBlockData());e.setGlowing(true);e.setGlowColorOverride(Color.AQUA);e.setVisibleByDefault(false);e.setPersistent(false);});p.showEntity(r.plugin,display);scans.computeIfAbsent(p.getUniqueId(),u->new ArrayList<>()).add(display);Bukkit.getScheduler().runTaskLater(r.plugin,()->{display.remove();List<BlockDisplay> list=scans.get(p.getUniqueId());if(list!=null){list.remove(display);if(list.isEmpty())scans.remove(p.getUniqueId());}},120);}}
 public void acceptedAttack(Player p,LivingEntity target){if(c().buff(p,"life_allied_fire")&&fireReady.getOrDefault(p.getUniqueId(),0L)<=now()){fireReady.put(p.getUniqueId(),now()+1000);r.damage().raw(p,target,3,CombatDamageService.DamageKind.RUNE);}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void immunity(EntityPotionEffectEvent e){if(e.getEntity() instanceof Player p&&c().buff(p,"life_immunity")&&e.getNewEffect()!=null&&RpgCombatListener.harmful(e.getNewEffect().getType()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void combust(EntityCombustEvent e){if(e.getEntity() instanceof Player p&&c().buff(p,"life_immunity"))e.setCancelled(true);}
 public void beginFishing(Player p){if(bait.getOrDefault(p.getUniqueId(),0)>0)baitedHook.add(p.getUniqueId());else baitedHook.remove(p.getUniqueId());refreshFishingLuck(p);}
 public void biteFishing(Player p){int n=bait.getOrDefault(p.getUniqueId(),0);if(n>0){bait.put(p.getUniqueId(),n-1);baitedHook.add(p.getUniqueId());}else baitedHook.remove(p.getUniqueId());}
 public void endFishing(Player p){Bukkit.getScheduler().runTask(r.plugin,()->baitedHook.remove(p.getUniqueId()));}
 private static String pct(double fraction){return String.format(Locale.ROOT,"%.0f%%",fraction*100);}
 private String primaryName(LifeProfession l){return switch(l){case MINER->"광맥 스캔";case FARMER->"봄바람 일괄 수확";case ANGLER->"어군 집결 밑밥";case CARPENTER->"건축가의 손길";case BLACKSMITH->"현장 급속 수리";case CHEF->"즉석 셰프 특식";};}
 private String finisherName(Player p,LifeProfession l){String b=r.lifeLevel(p)>=10?r.lifeSpec(p):"";if(b.isEmpty())return switch(l){case MINER->"광부의 집중";case FARMER->"봄의 축복";case ANGLER->"작은 황금 어장";case CARPENTER->"안전한 제작";case BLACKSMITH->"지오드 감정";case CHEF->"모두의 요리솥";};boolean a=b.equals("A");return switch(l){case MINER->a?"심연의 보석맥":"3×3 굴착";case FARMER->a?"황금 완숙":"풍년 오라";case ANGLER->a?"칠대양 황금 어장":"심해 월척";case CARPENTER->a?"황실 건축 비전":"산림 일괄 벌목";case BLACKSMITH->a?"별빛 명장 감정":"무기 벼리기";case CHEF->a?"황금 통합 요리솥":"비약 드링크";};}
 public String hudText(Player p){LifeProfession l=r.getLife(p);if(l==null)return "";int level=r.lifeLevel(p),star=r.getSignatures().star(p.getInventory().getItemInMainHand()),chain=r.perk(p,RpgDomain.LIFE,"chain");String state=switch(l){
  case MINER->"자석수납 "+(level>=5?"ON":"Lv.5")+" · 연쇄 "+(RpgRules.oreChainCap(level,star,0)+(int)(chain*r.cfg("rpg.perks.chain.ore-per-rank",1)))+"칸"+(excavation(p)?" · 3×3 ON":geodeMultiplier(p)>1?" · 지오드 ×"+geodeMultiplier(p):"");
  case FARMER->"수확 "+(level>=10?"5×5":"3×3")+" · 재파종 ON"+(cropMultiplier(p)>1?" · 풍년 ×2":"")+((chain>0||star>=3)?" · 추가 "+((int)(chain*r.cfg("rpg.perks.chain.crop-per-rank",2))+(star>=3?2:0))+"칸":"");
  case ANGLER->"입질 -"+pct(1-waitMultiplier(p))+" · 밑밥 "+bait.getOrDefault(p.getUniqueId(),0)+"회"+(fishingTreasureLuck(p)>0?" · 보물 행운 +"+String.format(Locale.ROOT,"%.0f",fishingTreasureLuck(p)):doubleFish(p)?" · 월척 ×2 · 감정 +"+pct(appraisalBonus(p)):fishingSizeWeight(p)>1?" · 대물 UP":"");
  case CARPENTER->"벌목 "+Math.min(48,16+level/2+(star>=3?2:0)+(int)(chain*r.cfg("rpg.perks.chain.log-per-rank",3)))+"원목 · 가구 재료 -45%"+(buildRange(p)>0?" · 사거리 +3.5m":"")+(fallReduction(p)>=1?" · 낙하 면역":"");
  case BLACKSMITH->"룬·감정 공임 무료 · 명장 "+pct(Math.min(1,r.cfg("runes.masterwork-chance",.25)+masterworkBonus(p)+(star>=7?.15:0)))+(c().buff(p,"life_allied_fire")?" · 무기 벼리기 ON":"");
  case CHEF->"만찬 재료 -40% · ★★★ +35%"+(c().buff(p,"life_immunity")?" · 비약 면역 ON":healthBonus(p)>0?" · 통합 만찬 ON":zones.stream().anyMatch(z->z.kind.equals("pot")&&z.owner.equals(p)&&z.until>now())?" · 요리솥 ON":"");
 };return "<gold>"+l.display+" Lv."+level+"</gold> <gray>│</gray> <aqua>"+state+"</aqua> <gray>│</gray> <white>["+(l==LifeProfession.ANGLER?"Shift+우":"우")+"] "+primaryName(l)+": "+c().cdText(p,RpgDomain.LIFE,"primary")+" [F] "+finisherName(p,l)+": "+c().cdText(p,RpgDomain.LIFE,"finisher");}
 public void hud(Player p){String text=hudText(p);if(!text.isEmpty())p.sendActionBar(TextUtil.mm(text));}
 @EventHandler public void quit(PlayerQuitEvent e){clear(e.getPlayer(),RpgDomain.LIFE);}@EventHandler public void death(PlayerDeathEvent e){clear(e.getEntity(),RpgDomain.LIFE);}
}
